fun toAdjust(row: AdjustmentRow): (Int) -> Int = when (row.kind) {
    "add" -> { g -> g + row.value }
    "less" -> { g -> g * (100 - row.value) / 100 }
    "atLeast" -> { g -> maxOf(g, row.value) }
    "atMost" -> { g -> minOf(g, row.value) }
    else -> throw IllegalArgumentException("unknown adjustment ${row.kind}")
}

