static Function<Integer, Integer> toAdjust(AdjustmentRow row) {
    return switch (row.kind()) {
        case "add" -> g -> g + row.value();
        case "less" -> g -> g * (100 - row.value()) / 100;
        case "atLeast" -> g -> Math.max(g, row.value());
        case "atMost" -> g -> Math.min(g, row.value());
        default -> throw new IllegalArgumentException("unknown adjustment " + row.kind());
    };
}

static Function<Integer, Integer> measure(String ingredient, List<AdjustmentRow> rows) {
    return rows.stream()
            .map(Kitchen::toAdjust)                               // 1. rows to functions
            .reduce(gramsFor(ingredient), Function::andThen);     // 2. one function, converter first
}

Function<Integer, Integer> sugar = measure("sugar", myRows);

sugar.apply(500);   // 425 -> 382 -> 382 -> 300
sugar.apply(50);    // 42 -> 37 -> 50 -> 50

